using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using CommandCodeManager;
using ModernHost;
public static class OpenCodeChecks {
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_open_v2(byte[] file,out IntPtr db,int flags,IntPtr vfs);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_exec(IntPtr db,byte[] sql,IntPtr callback,IntPtr argument,IntPtr error);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_close(IntPtr db);
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static string Quote(string value){return "'"+value.Replace("'","''")+"'";}
    static string Message(string provider,int input,int output,int cache,int reasoning){return new JavaScriptSerializer().Serialize(new{role="assistant",model=new{providerID=provider,id="fixture-model"},tokens=new{input=input,output=output,reasoning=reasoning,cache=new{read=cache,write=0}},cost=.1});}
    public static string Run(string directory){Directory.CreateDirectory(directory);string file=Path.Combine(directory,"统计测试.db");IntPtr db;if(sqlite3_open_v2(Encoding.UTF8.GetBytes(file+"\0"),out db,6,IntPtr.Zero)!=0)throw new Exception("fixture database creation failed");long now=(long)(DateTimeOffset.UtcNow-new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero)).TotalMilliseconds;string first=Quote(Message("fixture-provider",2,3,7,11)),second=Quote(Message("fixture-provider",13,17,19,23)),legacy=Quote(Message("fixture-provider",29,31,37,41));string sql="CREATE TABLE message(id TEXT PRIMARY KEY,session_id TEXT,time_created INTEGER,data TEXT);CREATE TABLE session_v2(id TEXT PRIMARY KEY,fork_session_id TEXT,time_created INTEGER);CREATE TABLE session_message(id TEXT PRIMARY KEY,session_id TEXT,type TEXT,time_created INTEGER,data TEXT);INSERT INTO session_v2 VALUES('normal',NULL,"+(now-10000)+");INSERT INTO session_v2 VALUES('fork','normal',"+(now-1000)+");INSERT INTO message VALUES('duplicate','old',"+(now-3000)+","+first+");INSERT INTO message VALUES('legacy','old',"+(now-2000)+","+legacy+");INSERT INTO session_message VALUES('duplicate','normal','assistant',"+(now-3000)+","+first+");INSERT INTO session_message VALUES('new','normal','assistant',"+(now-2000)+","+second+");INSERT INTO session_message VALUES('fork-copy','fork','assistant',"+(now-3000)+","+first+");";try{if(sqlite3_exec(db,Encoding.UTF8.GetBytes(sql+"\0"),IntPtr.Zero,IntPtr.Zero,IntPtr.Zero)!=0)throw new Exception("fixture SQL failed");}finally{sqlite3_close(db);}
        using(var reader=new ReadOnlySqlite(file)){bool refused=false;try{reader.Query("DELETE FROM message");}catch(InvalidOperationException){refused=true;}Check(refused,"reader must reject writes");Check(reader.Query("SELECT id FROM message").Count==2,"readonly failure changed database");}
        var credentials=new List<OpenCodeCredential>{new OpenCodeCredential{Id="cred_old",Provider="fixture-provider",Value=OpenCodeService.KeyValue("old-fixture-key"),Active=true},new OpenCodeCredential{Id="cred_other",Provider="other-provider",Value=OpenCodeService.KeyValue("other-fixture-key"),Active=true}};var calls=new List<string>();
        Func<string,string,object,Task<Dictionary<string,object>>> api=(path,method,body)=>{calls.Add(method+" "+path);if(path=="/api/credential"){string raw=new JavaScriptSerializer().Serialize(body);var request=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(raw);Check(Core.Boolean(request,"activate")==false,"new credential must not change active identity before activation");credentials.Add(new OpenCodeCredential{Id="cred_new",Provider=Core.Text(request,"integrationID"),Value=new JavaScriptSerializer().Serialize(Core.Value(request,"value")),Active=false});return Task.FromResult(new Dictionary<string,object>{{"data",new Dictionary<string,object>{{"id","cred_new"}}}});}if(path=="/api/credential/cred_new/activate"){foreach(var credential in credentials.Where(item=>item.Provider=="fixture-provider"))credential.Active=credential.Id=="cred_new";return Task.FromResult(new Dictionary<string,object>());}throw new Exception("unexpected API request");};
        using(var service=new OpenCodeService(file,api,()=>credentials,directory)){var rows=service.Records();Check(rows.Count==3,"legacy/v2 dedup or fork exclusion failed");Check(rows.Sum(row=>row.Total)==233,"cache/reasoning total failed");Check(object.ReferenceEquals(rows,service.Records()),"cached reads rescan database");var account=new Account{Id="fixture-account",Name="fixture",Platform="opencode",ProviderId="fixture-provider"};var data=service.Fetch(account,OpenCodeService.KeyValue("new-fixture-key")).GetAwaiter().GetResult();Check(data.TotalTokens==233&&data.Models.Length==1&&data.Models[0].Tokens==233,"provider/model aggregation failed");Check(data.MonthlyTotal==null&&data.Remaining==null&&data.Limited==null,"unsupported quota was fabricated");var history=service.History(account,new HistoryQuery{Grain="day",Page=0});Check(history.Complete&&history.Rows.Length==7&&history.Rows.Sum(row=>row.Tokens)==233,"daily aggregate failed");string id=service.Switch(account,OpenCodeService.KeyValue("new-fixture-key")).GetAwaiter().GetResult();Check(id=="cred_new"&&credentials.Single(item=>item.Provider=="other-provider").Active,"switch altered another provider");Check(calls.SequenceEqual(new[]{"POST /api/credential","POST /api/credential/cred_new/activate"}),"switch used nonofficial mutation");string backup=File.ReadAllText(Path.Combine(directory,"opencode-before-switch.encrypted"));Check(!backup.Contains("old-fixture-key")&&Core.Decrypt(backup).Contains("old-fixture-key"),"switch backup is not encrypted");}
        var portable=new[]{new PortableAccount{Name="OpenCode fixture",Platform="opencode",ProviderId="fixture-provider",ApiKey=OpenCodeService.KeyValue("new-fixture-key")}};string encrypted=AccountTransfer.Encrypt(portable,"fixture-password");var restored=AccountTransfer.Decrypt(encrypted,"fixture-password");Check(restored[0].Platform=="opencode"&&restored[0].ProviderId=="fixture-provider"&&OpenCodeService.Fingerprint(restored[0].ApiKey)==OpenCodeService.Fingerprint(portable[0].ApiKey),"OpenCode portable transfer failed");return "PASS: read-only SQLite, Unicode paths, v1/v2 dedup, fork exclusion, cache+reasoning totals, provider/model/day aggregation, cached reads, unsupported quota honesty, isolated official account switch, encrypted backup and portable OpenCode credentials";
    }
}
